from pydantic import BaseModel, Field

class MonthlyConstructionData(BaseModel):
    """A single monthly data point extracted from a report, including metadata for conflict resolution."""
    report_release_date: str = Field(
        description="The release date of the report containing this data (YYYY-MM-DD), used for conflict resolution"
    )
    data_month: str = Field(
        description="The month the data refers to, in YYYY-MM format"
    )
    value: float = Field(
        description="The seasonally adjusted number of units under construction (in thousands), e.g. 794.0 for 794,000"
    )
    status: str = Field(
        description="Status of the data point (e.g. 'Preliminary', 'Revised', or 'Preliminary/Revised')"
    )
    metric_description: str = Field(
        description="The specific metric reported (e.g. 'New Privately-Owned Housing Units Under Construction')"
    )

class Parse(BaseModel):
    monthly_data_points: list[MonthlyConstructionData]
